import type * as Icons from 'lucide-react';

/* ------------------------------------------------------------------
   Loan catalogue — the single source of truth for every product page.

   `data.ts` projects this into the summary shape the cards and carousels
   already use, so a product is added in exactly one place and every
   surface picks it up.

   RATES: `rate` is only filled where a published starting rate could be
   verified (see RATES_AS_OF in data.ts). Everything else is null and the
   UI shows "On request" rather than inventing a number.
------------------------------------------------------------------ */

export type Family={id:string;name:string;blurb:string;icon:keyof typeof Icons};

export type Product={
  id:string;
  family:string;
  name:string;
  description:string;          // one-line, used on cards
  icon:keyof typeof Icons;
  tag?:string;
  rate:string|null;            // null => not verified, shown as "On request"
  max:string;                  // indicative ceiling, phrased as a range
  tenure:string;
  what:string;                 // what it is
  suitedTo:string[];           // who it is for
  uses:string[];               // common uses
  eligibility:string[];
  docs:string[];
  fees:[string,string][];
  repayment:string;
  advantages:string[];
  considerations:string[];
  faqs:[string,string][];
};

export const families:Family[]=[
  {id:'personal',   name:'Personal Loans',        blurb:'Unsecured borrowing for planned and unplanned expenses.',              icon:'WalletCards'},
  {id:'business',   name:'Business Loans',        blurb:'Working capital, expansion and equipment finance for businesses.',      icon:'BriefcaseBusiness'},
  {id:'property',   name:'Loan Against Property', blurb:'Borrow against residential, commercial or open land you already own.',  icon:'Building2'},
  {id:'vehicle',    name:'Vehicle Loans',         blurb:'Finance for two-wheelers, cars and commercial vehicles.',               icon:'CarFront'},
  {id:'home',       name:'Home Loans',            blurb:'Purchase, construction, transfer and top-up finance for a home.',       icon:'House'},
  {id:'gold',       name:'Gold Loans',            blurb:'Secured against gold jewellery, usually the fastest to disburse.',      icon:'Gem'},
  {id:'securities', name:'Loan Against Securities',blurb:'Raise money against investments without selling them.',                icon:'LineChart'},
  {id:'education',  name:'Education Loans',       blurb:'Tuition, living costs and travel for study in India or abroad.',        icon:'GraduationCap'},
];

/* shared building blocks — repeated criteria stated once */
