const kycDocs=['PAN card and Aadhaar','Recent passport-size photograph','Address proof (utility bill, passport or rent agreement)'];
const incomeDocs=['Last 3 months bank statements','Salary slips for 3 months, or 2 years ITR if self-employed'];
const stdFees:[string,string][]=[
  ['Processing fee','Charged by the lender, commonly a percentage of the sanctioned amount. See the offer document for the exact figure.'],
  ['Prepayment / foreclosure','Nil on floating-rate loans to individuals by RBI rule. Fixed-rate products may levy a charge.'],
  ['Late payment','A penal charge applies on any overdue instalment. The rate is set out in your loan agreement.'],
  ['Documentation / stamping','At actuals, where applicable in your state.'],
];
const stdRepay='Repaid in equal monthly instalments (EMIs) by auto-debit from your bank account. The first EMI usually falls due a month after disbursal.';

const commonFaqs:[string,string][]=[
  ['Does checking my eligibility affect my credit score?','No. An eligibility check on this platform is a soft enquiry — invisible to other lenders and with no effect on your score. A hard enquiry happens only when you formally accept an offer and the lender begins underwriting.'],
  ['How long does approval take?','It depends on the product and the lender. Unsecured loans are generally quicker than secured ones, which need the asset to be valued and legally verified. Your chosen lender will confirm timelines.'],
  ['Can I prepay or foreclose early?','Most lenders allow it. Floating-rate loans to individuals carry no foreclosure charge under RBI rules; fixed-rate products may. The exact terms appear on every offer before you accept.'],
];

